const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '2:3' },
      { kind: 'text', payload: '2' },
      { kind: 'text', payload: '3' },
      { kind: 'text', payload: '线段按 2:3 分成两段' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var margin = Math.min(64, Math.max(20, W * 0.09));
    var x0 = margin;
    var x1 = W - margin;
    if (x1 - x0 < 80) {
      x0 = 16;
      x1 = W - 16;
    }
    var y = H * 0.54;
    var span = x1 - x0;
    var xm = x0 + span * 2 / 5;
    var fs = Math.max(14, Math.min(24, Math.round(Math.min(W, H) * 0.055)));
    var tick = Math.max(8, fs * 0.6);

    var left = visualSdk.polyline([[x0, y], [xm, y]]);
    var right = visualSdk.polyline([[xm, y], [x1, y]]);
    var divider = visualSdk.polyline([[xm, y - tick], [xm, y + tick]]);
    var capL = visualSdk.polyline([[x0, y - tick], [x0, y + tick]]);
    var capR = visualSdk.polyline([[x1, y - tick], [x1, y + tick]]);
    var dot = visualSdk.circle(xm, y, Math.max(2.5, fs * 0.12));

    return {
      schemaVersion: 1,
      sceneId: 'ratio-2-3',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'leftSeg', commands: left },
        { id: 'rightSeg', commands: right },
        { id: 'divider', commands: divider },
        { id: 'capL', commands: capL },
        { id: 'capR', commands: capR },
        { id: 'dot', commands: dot }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'leftSeg', stroke: '#1f5fa8', strokeWidth: 5, fill: 'none' },
          { type: 'path', pathId: 'rightSeg', stroke: '#c94c2b', strokeWidth: 5, fill: 'none' },
          { type: 'path', pathId: 'divider', stroke: '#26354a', strokeWidth: 2.5, fill: 'none' },
          { type: 'path', pathId: 'capL', stroke: '#26354a', strokeWidth: 2.5, fill: 'none' },
          { type: 'path', pathId: 'capR', stroke: '#26354a', strokeWidth: 2.5, fill: 'none' },
          { type: 'path', pathId: 'dot', fill: '#26354a', stroke: '#26354a' },
          {
            type: 'label',
            text: '2',
            x: (x0 + xm) / 2,
            y: y - fs * 1.25,
            fontSize: fs,
            fill: '#1f5fa8',
            textAnchor: 'middle',
            dominantBaseline: 'middle',
            fontWeight: 600
          },
          {
            type: 'label',
            text: '3',
            x: (xm + x1) / 2,
            y: y - fs * 1.25,
            fontSize: fs,
            fill: '#c94c2b',
            textAnchor: 'middle',
            dominantBaseline: 'middle',
            fontWeight: 600
          },
          {
            type: 'label',
            text: '2:3',
            x: (x0 + x1) / 2,
            y: y + fs * 2.0,
            fontSize: fs * 1.35,
            fill: '#26354a',
            textAnchor: 'middle',
            dominantBaseline: 'middle',
            fontWeight: 700
          },
          {
            type: 'label',
            text: '线段按 2:3 分成两段',
            x: (x0 + x1) / 2,
            y: Math.max(fs * 1.8, H * 0.16),
            fontSize: fs * 0.95,
            fill: '#40516a',
            textAnchor: 'middle',
            dominantBaseline: 'middle'
          }
        ]
      }
    };
  }
};
